#!/usr/bin/env python3
from pathlib import Path
import base64,zlib,hashlib,sys
EXPECTED="9c4bad55218afbbfa34d5ceaf6bab78f646624ae2040cd908a6056991b45f917"
DATA=""""""
out=Path(sys.argv[1] if len(sys.argv)>1 else "/tmp/v654.patch")
raw=zlib.decompress(base64.b64decode(DATA))
sha=hashlib.sha256(raw).hexdigest()
if sha != EXPECTED:
    raise SystemExit(f"BLOCKED embedded patch checksum mismatch {sha}")
out.write_bytes(raw)
print(f"PATCH_SHA256={sha}")
print(f"PATCH_BYTES={len(raw)}")
